#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

fn issctype(rep: DataType) -> bool {
    match rep {
        DataType::ScalarInt
        | DataType::ScalarFloat
        | DataType::ScalarComplex
        | DataType::ScalarBool
        | DataType::ScalarString => true,
        DataType::ArrayType
        | DataType::CompositeType
        | DataType::UnknownType => false,
    }
}

fn main() {
    // Some example usages
    assert_eq!(issctype(DataType::ScalarInt), true);
    assert_eq!(issctype(DataType::ScalarFloat), true);
    assert_eq!(issctype(DataType::ScalarComplex), true);
    assert_eq!(issctype(DataType::ScalarBool), true);
    assert_eq!(issctype(DataType::ScalarString), true);

    assert_eq!(issctype(DataType::ArrayType), false);
    assert_eq!(issctype(DataType::CompositeType), false);
    assert_eq!(issctype(DataType::UnknownType), false);

    println!("All tests passed!");
}